mapper.select:
select A.BOOKSET_ID as booksetId, B.BOOKSET_NAME as booksetName, C.BUSI_ID as bondId, D.FINPROD_ABBR as bondName, DATE_FORMAT(A.HAPPEN_DATE,'%Y-%m-%d') as vdate, (A.END_DAYS_COST_AMT-A.TDY_COST_AMT) as changeAmt, A.DAILYDSC_YIELD as realRate, D.TRADE_MARKET as market, A.TDY_COST_AMT as tdyCostAmt, case when A.TDY_POSITION=0 then 0 else A.TDY_COST_AMT/A.TDY_POSITION end as tdyNPAmt, case when A.TDY_POSITION=0 then 0 else (A.TDY_COST_AMT + A.TDY_INTINCEXP_ADD)/A.TDY_POSITION end as tdyFPAmt from BOK_STAT_DET_POSIITON A, BOK_BOOKSET B , BOK_DETAIL_ID C , FIN_PRODUCT D where A.BOOKSET_ID=B.BOOKSET_ID and A.BOOKSET_ID=C.BOOKSET_ID and A.BOK_DETAIL_ID=C.BOK_DETAIL_ID and C.BUSI_ID=D.FINPROD_ID
and D.FINPROD_TYPE=#{finprodType}
and C.INV_AIM !=#{invAim}
and A.BOOKSET_ID=#{booksetId}
and C.BUSI_ID=#{bondId}
and A.HAPPEN_DATE >= STR_TO_DATE(#{vDateBegin},'%Y-%m-%d')
and A.HAPPEN_DATE <= STR_TO_DATE(#{vDateEnd},'%Y-%m-%d')
and D.TRADE_MARKET=#{market}
